<script setup lang="ts">
import { onMounted } from 'vue';

declare global {
  interface Window {
    goToView: (viewName: string) => void
    switchTab: (prefix: string, tabId: string) => void
    selectPatient: (id: number) => void
    switchMedicalTab: (tabName: string) => void
    filterByScenario: (key: string) => void
    onModelSearch: () => void
    showAiPreview: () => void
    closeAiPreview: () => void
  }
}

onMounted(() => {
  // 加载 Font Awesome CSS
  if (!document.getElementById('fa-css')) {
    const link = document.createElement('link');
    link.id = 'fa-css';
    link.rel = 'stylesheet';
    link.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css';
    document.head.appendChild(link);
  }
  // 默认选中第一个患者
  if (typeof selectPatient === 'function') selectPatient(1);

  // 初始化"其他"下拉菜单
  const trigger = document.getElementById('his-other-trigger');
  const dropdown = document.getElementById('his-dropdown');
  if (trigger && dropdown) {
    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      dropdown.style.display = dropdown.style.display === 'block' ? 'none' : 'block';
    });
    document.addEventListener('click', () => {
      dropdown.style.display = 'none';
    });
    dropdown.addEventListener('click', (e) => e.stopPropagation());
  }

  // 复用 his1 视图中的 logo base64 到所有 .logo-img
  const sourceLogo = document.querySelector('#view-his1 .top-nav-header img');
  if (sourceLogo) {
    const src = sourceLogo.getAttribute('src') || '';
    document.querySelectorAll<HTMLImageElement>('.logo-img').forEach(img => {
      if (!img.getAttribute('src')) img.setAttribute('src', src);
    });
  }
  // 渲染工作台模型卡片
  if (typeof renderScenarioTags === 'function') renderScenarioTags();
  if (typeof renderModelGrid === 'function') renderModelGrid();
  // 渲染模型详情任务列表
  if (typeof renderModelTasks === 'function') renderModelTasks();
  // 渲染 AI 辅助诊断表格
  if (typeof renderAiDiagnosisTable === 'function') renderAiDiagnosisTable();
  // 处理 URL 参数 ?view=xxx 直接跳转
  try {
    const viewParam = new URLSearchParams(window.location.search).get('view');
    if (viewParam && ['his', 'his1', 'his2', 'his3', 'unified-entry', 'model-detail', 'ai-diagnosis'].includes(viewParam)) {
      goToView(viewParam);
    }
  } catch (e) { /* ignore */ }
});

// ========== 视图切换(全局函数,供 onclick 调用) ==========
    function goToView(viewName: string) {
      // 直接操作 style.display,不依赖 CSS class
      ['his', 'his1', 'his2', 'his3', 'unified-entry', 'model-detail', 'ai-diagnosis'].forEach(name => {
        const el = document.getElementById('view-' + name);
        if (el) {
          el.style.setProperty('display', 'none', 'important');
          el.setAttribute('hidden', '');
        }
      });
      const target = document.getElementById('view-' + viewName);
      if (target) {
        target.style.setProperty('display', 'flex', 'important');
        target.removeAttribute('hidden');
      }
      // 关闭 HIS 下拉菜单
      const dd = document.getElementById('his-dropdown');
      if (dd) dd.style.display = 'none';
      window.scrollTo(0, 0);
      // 切换到模型工作台时，重新渲染内容
      if (viewName === 'unified-entry') {
        if (typeof renderScenarioTags === 'function') renderScenarioTags();
        if (typeof renderModelGrid === 'function') renderModelGrid();
      }
      // 重置所有可能的滚动位置到顶部
      if (target) target.scrollTop = 0;
      window.scrollTo(0, 0);
    }
    window.goToView = goToView;

    // ========== his1/his2/his3 顶部 Tab 切换(全局函数) ==========
    function switchTab(prefix: string, tabId: string) {
      if (tabId === 'overview') {
        goToView('his');
        return;
      }
      const tabs = document.querySelectorAll<HTMLElement>('[data-' + prefix + '-tab]');
      const bodies = document.querySelectorAll<HTMLElement>('[data-' + prefix + '-body]');
      tabs.forEach(t => t.classList.toggle('ant-menu-item-selected', t.dataset[prefix + 'Tab'] === tabId));
      bodies.forEach(b => {
        b.style.display = b.dataset[prefix + 'Body'] === tabId ? 'flex' : 'none';
      });
    }
    window.switchTab = switchTab;

