    let activeScenarioTag = 'all';

    function getModelIconClass(icon: string) {
      return 'fa-solid ' + icon;
    }

    function renderScenarioTags() {
      const container = document.getElementById('scenario-tags');
      if (!container) return;
      container.innerHTML = scenarioTags.map((t: { key: string; name: string; count: number }) => {
        const isActive = t.key === activeScenarioTag;
        const activeClass = isActive ? ' scenario-tag-active' : '';
        return '<button onclick="filterByScenario(\'' + t.key + '\')" class="scenario-tag' + activeClass + '">' +
          t.name +
          '<span class="scenario-tag-count">' + t.count + '</span>' +
        '</button>';
      }).join('');
    }

    function filterByScenario(key: string) {
      activeScenarioTag = key;
      renderScenarioTags();
      renderModelGrid();
    }
    window.filterByScenario = filterByScenario;

    let modelSearchKeyword = '';

    function onModelSearch() {
      const input = document.getElementById('model-search-input') as HTMLInputElement | null;
      modelSearchKeyword = input ? input.value : '';
      renderModelGrid();
    }
    window.onModelSearch = onModelSearch;

    function getStatusBadge(status: string) {
      const map: Record<string, string> = {
        '已开通': 'status-badge status-badge-open',
        '已暂停': 'status-badge status-badge-paused',
        '已过期': 'status-badge status-badge-expired',
      };
      return map[status] || 'status-badge status-badge-expired';
    }

    function renderModelGrid() {
      const grid = document.getElementById('model-grid');
      if (!grid) return;

      const visibleScenarios = activeScenarioTag === 'all'
        ? modelScenarios
        : modelScenarios.filter(s => {
            if (activeScenarioTag === 'diagnosis') return s.name === '辅助诊断';
            if (activeScenarioTag === '3d') return s.name === '三维建模';
            return true;
          });

      grid.innerHTML = visibleScenarios.map(scenario => {
        let models = scenario.models;
        if (modelSearchKeyword) {
          const kw = modelSearchKeyword.toLowerCase();
          models = models.filter(m =>
            m.name.toLowerCase().includes(kw) ||
            m.vendorName.toLowerCase().includes(kw) ||
            m.desc.toLowerCase().includes(kw)
          );
        }
        if (models.length === 0) return '';

        const is3d = scenario.name === '三维建模';
        const barColor = 'bg-blue-500';
        const iconBg = 'bg-blue-50 border-blue-100 text-blue-600';

        const cardsHtml = models.map(m => {
          const statusClass = getStatusBadge(m.status);
          return '<div class="model-card" onclick="showAiPreview()">' +
            '<div class="model-card-top">' +
              '<div class="model-icon-box ' + iconBg + '">' +
                '<i class="' + getModelIconClass(m.icon) + '"></i>' +
              '</div>' +
              '<span class="' + statusClass + '">' + m.status + '</span>' +
            '</div>' +
            '<div class="model-card-body">' +
              '<h3>' + m.name + '</h3>' +
              '<p>' + m.desc + '</p>' +
            '</div>' +
            '<div class="model-card-bottom">' +
              '<span class="model-detail-link">进入 <i class="fas fa-chevron-right"></i></span>' +
            '</div>' +
          '</div>';
        }).join('');

        const displayName = scenario.name === '辅助诊断' ? '辅助诊断模型' : '三维建模模型';
        return '<div class="category-section">' +
          '<div class="category-header">' +
            '<div class="category-bar ' + barColor + '"></div>' +
            '<h2>' + displayName + '</h2>' +
            '<span class="category-count">共 ' + models.length + ' 个</span>' +
          '</div>' +
          '<div class="model-grid">' + cardsHtml + '</div>' +
        '</div>';
      }).join('');
    }

    function showAiPreview() {
      const overlay = document.getElementById('ai-preview-overlay');
      if (overlay) overlay.classList.add('show');
    }
    function closeAiPreview() {
      const overlay = document.getElementById('ai-preview-overlay');
      if (overlay) overlay.classList.remove('show');
    }
    window.showAiPreview = showAiPreview;
    window.closeAiPreview = closeAiPreview;

