        { id: 'T20260728005', patient: '刘建国', visit: '住院', time: '2026-07-28 13:21:09', dur: '2.5s', status: '已完成' },
      ];
      tbody.innerHTML = rows.map(r => (
        '<tr class="border-b border-slate-50 hover:bg-blue-50/30 transition-colors">' +
          '<td class="px-5 py-3 font-mono text-xs text-slate-500">' + r.id + '</td>' +
          '<td class="px-5 py-3 font-bold text-slate-900">' + r.patient + '</td>' +
          '<td class="px-5 py-3"><span class="text-[11px] font-medium px-2 py-0.5 rounded-full ' + (r.visit === '门诊' ? 'bg-blue-50 text-blue-700 border border-blue-100' : 'bg-purple-50 text-purple-700 border border-purple-100') + '">' + r.visit + '</span></td>' +
          '<td class="px-5 py-3 text-slate-600 text-xs">' + r.time + '</td>' +
          '<td class="px-5 py-3 text-slate-600 font-mono text-xs">' + r.dur + '</td>' +
          '<td class="px-5 py-3"><span class="text-[11px] font-medium px-2 py-0.5 rounded-full ' + (r.status === '已完成' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' : 'bg-amber-50 text-amber-700 border border-amber-100') + '">' + r.status + '</span></td>' +
          '<td class="px-5 py-3 text-right"><button class="text-xs text-blue-600 hover:text-blue-700 font-medium">查看</button></td>' +
        '</tr>'
      )).join('');
    }

    function renderAiDiagnosisTable() {
      const tbody = document.getElementById('ai-diagnosis-tbody');
      if (!tbody) return;
      const rows = [
        { no: 1, status: '已完成', type: 'CT肺结节AI筛查', time: '2026-06-15 10:23:15', name: '陈志明', id: '3204**********1263', gender: '男', age: 42, visit: '门诊', dept: '放射科', score: '89.5', scoreIcon: 'pass', taskStatus: '已完成' },
        { no: 2, status: '诊断中', type: '心电图AI智能分析', time: '2026-06-15 09:45:22', name: '王小红', id: '3205**********8741', gender: '女', age: 35, visit: '门诊', dept: '心内科', score: '82.3', scoreIcon: 'pass', taskStatus: '进行中' },
        { no: 3, status: '已完成', type: '病理切片AI筛查', time: '2026-06-15 08:30:12', name: '李明华', id: '3206**********5628', gender: '男', age: 58, visit: '住院', dept: '病理科', score: '94.1', scoreIcon: 'pass', taskStatus: '已完成' },
        { no: 4, status: '已完成', type: '临床决策支持', time: '2026-06-14 16:22:33', name: '张丽华', id: '3207**********9834', gender: '女', age: 62, visit: '住院', dept: '内科', score: '87.8', scoreIcon: 'pass', taskStatus: '已完成' },
        { no: 5, status: '待审核', type: '用药风险AI评估', time: '2026-06-14 14:15:47', name: '刘海波', id: '3208**********6721', gender: '男', age: 47, visit: '门诊', dept: '药剂科', score: '91.2', scoreIcon: 'pass', taskStatus: '待审核' },
        { no: 6, status: '诊断中', type: '慢病风险预测', time: '2026-06-14 11:05:30', name: '赵云龙', id: '3209**********3451', gender: '男', age: 56, visit: '体检', dept: '内分泌科', score: '76.4', scoreIcon: 'dash', taskStatus: '进行中' },
        { no: 7, status: '已完成', type: '检验结果智能解读', time: '2026-06-13 09:20:18', name: '孙晓芬', id: '3210**********7294', gender: '女', age: 51, visit: '门诊', dept: '检验科', score: '95.8', scoreIcon: 'pass', taskStatus: '已完成' },
        { no: 8, status: '待审核', type: '手术风险评估', time: '2026-06-13 15:42:05', name: '周国强', id: '3211**********5083', gender: '男', age: 68, visit: '住院', dept: '普外科', score: '73.6', scoreIcon: 'warn', taskStatus: '待审核' },
      ];
      const statusClass = (s: string) => s === '已完成' ? 'bg-green-100 text-green-700' : (s === '诊断中' || s === '进行中' ? 'bg-blue-100 text-blue-700' : 'bg-amber-100 text-amber-700');
      const scoreHtml = (r: { score: string; scoreIcon: string }) => {
        if (r.scoreIcon === 'pass') return '<div class="flex items-center gap-2"><span class="text-xs font-bold text-purple-600">' + r.score + '</span><i class="fas fa-check text-green-500 text-xs"></i></div>';
        if (r.scoreIcon === 'warn') return '<div class="flex items-center gap-2"><span class="text-xs font-bold text-purple-600">' + r.score + '</span><span style="font-size: 10px; color: #f59e0b;">⚠</span></div>';
        return '<div class="flex items-center gap-2"><span class="text-xs font-bold text-purple-600">' + r.score + '</span><span style="font-size: 10px; color: #94a3b8;">-</span></div>';
      };
      tbody.innerHTML = rows.map(r => (
        '<tr style="border-bottom: 1px solid #f1f5f9;">' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #64748b;">' + r.no + '</td>' +
          '<td style="padding: 12px 16px;"><span class="px-2 py-1 ' + statusClass(r.status) + ' text-[11px] font-medium rounded-full">' + r.status + '</span></td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #334155;">' + r.type + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #64748b;">' + r.time + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #334155;">' + r.name + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #64748b; font-family: monospace;">' + r.id + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #64748b;">' + r.gender + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #64748b;">' + r.age + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #64748b;">' + r.visit + '</td>' +
          '<td style="padding: 12px 16px; font-size: 12px; color: #334155;">' + r.dept + '</td>' +
          '<td style="padding: 12px 16px;">' + scoreHtml(r) + '</td>' +
          '<td style="padding: 12px 16px;"><span class="px-2 py-1 ' + statusClass(r.taskStatus) + ' text-[11px] font-medium rounded-full">' + r.taskStatus + '</span></td>' +
        '</tr>'
      )).join('');
    }
</script>

<style>
body { margin: 0; font-family: 'Microsoft YaHei', sans-serif; }

    /* ============== 顶部导航栏样式 (his1/his2/his3 共用) ============== */
    .top-nav-bar {
      width: 100%; height: 64px; background: white;
      border-bottom: 1px solid #e5e7eb;
      display: flex; align-items: center;
      position: relative; flex-shrink: 0;
    }
    .top-nav-header {
      height: 64px; font-size: 14px; font-weight: 400;
      color: rgba(0, 0, 0, 0.65); line-height: 64px;
      margin: 0 0 0 12px;
    }
    .top-nav-title {
      font-size: 16px; font-weight: 600; color: #002140;
      line-height: 64px; margin-left: 8px;
      display: flex; align-items: center; white-space: nowrap;
    }
    .top-nav-user {
      display: flex; align-items: center; gap: 8px;
      font-size: 13px; color: rgba(0, 0, 0, 0.65);
      cursor: pointer; height: 100%; padding: 0 20px;
      white-space: nowrap; margin-left: auto;
    }
    .top-nav-user:hover { color: rgba(0, 0, 0, 0.85); }

    /* Ant Design 风格菜单 */
    .ant-header-menu { margin-left: 24px; }
    .ant-menu-item {
      display: inline-flex; align-items: center; height: 100%;
      padding: 0 20px; font-size: 14px; color: rgba(0, 0, 0, 0.65);
      cursor: pointer; transition: color 0.3s, border-color 0.3s;
      border-bottom: 2px solid transparent; text-decoration: none;
      position: relative; top: 1px; white-space: nowrap;
      background: transparent !important;
      border-radius: 0 !important;
    }
    .ant-menu-item:hover { color: #1890ff; background: transparent !important; }
    .ant-menu-item-selected { color: #1890ff; border-bottom-color: #1890ff; background: transparent !important; border-radius: 0 !important; }
    .ant-menu-item-icon {
      display: inline-flex; align-items: center; margin-right: 8px; font-size: 14px;
    }
    .ant-menu-item-icon svg { display: block; }

    /* ============== HIS 门诊医生站样式 ============== */
    .his-dropdown {
      position: absolute; top: 100%; left: 0; padding-top: 4px; z-index: 50;
    }
    .his-dropdown-inner {
      background: white; color: #374151; border-radius: 4px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.15); border: 1px solid #e5e7eb;
