    }
    .his-dropdown-item {
      padding: 6px 12px; font-size: 12px; cursor: pointer; white-space: nowrap;
    }
    .his-dropdown-item:hover { background: #eff6ff; color: #1e40af; }

    /* 视图容器:用内联 style.display 控制,不用 class */
    .view-container { }

    .terminal-user-page { }

    /* HIS 患者列表选中态 */
    .patient-active { background: #374151 !important; }

    /* HIS Tab 选中态 */
    .medical-tab-active {
      color: #1e40af !important;
      font-weight: 700 !important;
      border-bottom: 2px solid #1e40af !important;
    }

    /* 自定义滚动条 */
    ::-webkit-scrollbar { width: 6px; height: 6px; }
    ::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 3px; }
    ::-webkit-scrollbar-track { background: transparent; }

.top-nav-subtitle { font-size: 12px; color: rgba(0, 0, 0, 0.45); margin-left: 0; white-space: nowrap; }
.top-nav-sep { width: 1px; height: 14px; background: #e5e7eb; margin: 0 8px; display: inline-block; vertical-align: middle; }

/* ============================================================
   AI 模型工作台 - 参考 ai.html 设计风格（蓝色系）
   ============================================================ */

/* Banner 卡片 */
.banner-card {
  position: relative;
  background: #fff;
  border-radius: 16px;
  padding: 24px 32px;
  margin-bottom: 32px;
  border: 1px solid rgba(226, 232, 240, 0.8);
  box-shadow: 0 1px 3px 0 rgba(0,0,0,0.04);
  overflow: hidden;
}
.banner-deco {
  position: absolute;
  right: 0; top: 0;
  width: 320px; height: 320px;
  background: linear-gradient(225deg, rgba(37,99,235,0.06) 0%, transparent 70%);
  border-bottom-left-radius: 100%;
  pointer-events: none;
}
.banner-inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}
@media (min-width: 768px) {
  .banner-inner { flex-direction: row; align-items: center; }
}
.banner-left { max-width: 680px; }
.banner-title {
  font-size: 24px;
  font-weight: 700;
  color: #0f172a;
  margin: 0;
  line-height: 1.3;
  letter-spacing: -0.5px;
}
.banner-desc {
  font-size: 14px;
  color: #64748b;
  margin: 4px 0 0;
  max-width: 672px;
  line-height: 1.6;
}
.banner-tags {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 16px;
}
.banner-tag-item {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 8px;
  background: #eff6ff;
  color: #1d4ed8;
  font-size: 12px;
  font-weight: 500;
  border: 1px solid #dbeafe;
}
.banner-tag-secondary {
  background: #f1f5f9;
  color: #334155;
  border-color: #e2e8f0;
}
.banner-tag-secondary i { color: #3b82f6; }
.banner-right {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

/* 流程图面板 */
.flow-panel {
  display: flex;
  align-items: center;
  gap: 0;
}
.flow-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.flow-circle {
  position: relative;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: transparent;
  border: 1.5px solid #d4dce6;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.2s;
}
.flow-item:hover .flow-circle {
  border-color: #93c5fd;
}
.flow-icon {
  font-size: 16px;
  color: #86909c;
}
.flow-label {
  font-size: 12px;
  color: #64748b;
  font-weight: 500;
  white-space: nowrap;
}
.flow-connector {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0 16px;
  margin-bottom: 18px;
}
.flow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #d4dce6;
}

/* 筛选栏 */
.filter-bar {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
}
@media (min-width: 640px) {
  .filter-bar { flex-direction: row; align-items: center; }
}
.filter-tabs-container {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  background: #fff;
  padding: 6px;
  border-radius: 12px;
  border: 1px solid #e2e8f0;
  box-shadow: 0 1px 3px 0 rgba(0,0,0,0.04);
  width: fit-content;
}
/* 筛选标签按钮 */
.scenario-tag {
  display: inline-flex;
  align-items: center;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 500;
  color: #475569;
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s;
  font-family: inherit;
}
.scenario-tag:hover {
  color: #0f172a;
  background: #f1f5f9;
}
.scenario-tag-active {
  background: #1d4ed8;
  color: #fff;
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(37, 99, 235, 0.35);
}
.scenario-tag-active:hover {
  background: #1d4ed8;
  color: #fff;
}
.scenario-tag-count {
  margin-left: 4px;
  padding: 1px 6px;
  border-radius: 999px;
  background: #f1f5f9;
  color: #475569;
  font-size: 10px;
  font-weight: 500;
}
.scenario-tag-active .scenario-tag-count {
  background: rgba(255,255,255,0.2);
  color: #fff;
}
.filter-search {
  position: relative;
  width: 100%;
  max-width: 288px;
}
.filter-search input {
  width: 100%;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 8px 16px 8px 40px;
  font-size: 12px;
  color: #0f172a;
  outline: none;
  transition: all 0.15s;
  box-shadow: 0 1px 3px 0 rgba(0,0,0,0.04);
  font-family: inherit;
}
.filter-search input::placeholder { color: #94a3b8; }
.filter-search input:focus {
  border-color: #165DFF;
  box-shadow: 0 0 0 2px rgba(22,93,255,0.15);
}
.filter-search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  font-size: 12px;
}

/* 分区标题 */
.category-section { margin-bottom: 32px; }
.category-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
}
.category-bar {
  width: 6px;
  height: 16px;
  border-radius: 3px;
}
.category-bar.bg-blue-500 { background: #165DFF; }
.category-header h2 {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  margin: 0;
  letter-spacing: 0.3px;
}
.category-count {
  font-size: 12px;
  color: #94a3b8;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

/* 模型网格 */
.model-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 20px;
}
@media (min-width: 640px) { .model-grid { grid-template-columns: repeat(2, 1fr); } }
@media (min-width: 1024px) { .model-grid { grid-template-columns: repeat(4, 1fr); } }

/* 模型卡片 */
.model-card {
  background: #fff;
  border-radius: 12px;
  padding: 20px;
  border: 1px solid rgba(226, 232, 240, 0.8);
  box-shadow: 0 1px 3px 0 rgba(0,0,0,0.04);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all 0.2s ease-in-out;
}
.model-card:hover {
  border-color: #93c5fd;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1), 0 4px 16px rgba(0,0,0,0.06);
}
.model-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}
.model-icon-box {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  border: 1px solid;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  transition: transform 0.15s;
}
.model-card:hover .model-icon-box { transform: scale(1.05); }
.model-icon-box.bg-blue-50 { background: #eff6ff; }
.model-icon-box.border-blue-100 { border-color: #dbeafe; }
.model-icon-box.text-blue-600 { color: #165DFF; }
.model-card-body h3 {
  font-size: 14px;
  font-weight: 700;
  color: #0f172a;
  margin: 0 0 4px;
  line-height: 1.3;
  transition: color 0.15s;
}
.model-card:hover .model-card-body h3 { color: #165DFF; }
.model-card-body p {
  font-size: 12px;
  color: #64748b;
  line-height: 1.6;
  margin: 0 0 16px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.model-card-bottom {
  padding-top: 12px;
  border-top: 1px solid #f1f5f9;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: #94a3b8;
}
.model-vendor {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 170px;
  display: inline-block;
}
.model-detail-link {
  color: #165DFF;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: transform 0.15s;
  font-size: 11px;
}
.model-card:hover .model-detail-link { transform: translateX(2px); }
.model-detail-link i { font-size: 9px; }

/* 状态徽章 */
.status-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  border-radius: 999px;
  border: 1px solid;
  font-size: 11px;
  font-weight: 500;
  line-height: 1;
}
.status-badge-open {
  background: #eff6ff;
  color: #165DFF;
  border-color: #dbeafe;
}
.status-badge-paused {
  background: #fffbeb;
  color: #d97706;
  border-color: #fde68a;
}
.status-badge-expired {
  background: #fff1f2;
  color: #e11d48;
  border-color: #fecdd3;
}

.unified-scrollbar::-webkit-scrollbar { display: none; }
.unified-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

/* ai.png 全屏预览 */
.ai-preview-overlay {
  display: none; position: fixed; inset: 0; z-index: 9999;
  background: rgba(0,0,0,0.75);
  justify-content: center; align-items: center;
}
.ai-preview-overlay.show { display: flex; }
.ai-preview-overlay img {
  max-width: 90vw; max-height: 90vh;
  border-radius: 8px; box-shadow: 0 20px 60px rgba(0,0,0,0.4);
}
.ai-preview-close {
  position: absolute; top: 20px; right: 20px;
  width: 40px; height: 40px; border-radius: 50%;
  background: rgba(255,255,255,0.15); color: #fff;
  font-size: 20px; cursor: pointer; border: none;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.2s;
}
.ai-preview-close:hover { background: rgba(255,255,255,0.3); }
</style>
